public class JPrintDigitsReverse {
	public static void main(String[] args) {
		//Khatwa 1: Ta'reef al-mutaghayyirat allati nahtajuha li hadha al-barnamaj
		int num = 1234;
		int lastDigit;
		//Khatwa 2: Tiba'at arqam al-adad al-sahih min al-yamin ila al-yasar
		do {
			//Khatwa 2.1: Istikhraj al-rakam al-akhir fi al-adad
			lastDigit = num % 10;
			//Khatwa 2.2: Tibaa al-rakam al-mustakhradj
			System.out.println(lastDigit);
			//Khatwa 2.3: Izalat al-rakam al-akhiran min al-adad
			num = num / 10;
		} while (num > 0);
	}
}
